{"code":"import pandas as pd
import numpy as np

raw = pd.read_csv('raw_responses.csv')
pipeline = pd.read_csv('pipeline_output.csv')

# Let's write a python scorer and compare column by column

def round_half_up(val):
    # Halves always round up, so 4.5 becomes 5 and 10.5 becomes 11
    return int(np.floor(val + 0.5))

def score_phq9(row):
    cols = [f'phq9_{i}' for i in range(1, 10)]
    vals = []
    for c in cols:
        v = row[c]
        if pd.isna(v) or v < 0 or v > 3:
            vals.append(np.nan)
        else:
            vals.append(int(v))

    # Self harm flag based on phq9_9
    v9 = row['phq9_9']
    if pd.isna(v9) or v9 < 0 or v9 > 3:
        sh_flag = np.nan
    else:
        sh_flag = (int(v9) > 0)

    n_missing = pd.isna(vals).sum()
    if n_missing >= 2:
        return np.nan, np.nan, np.nan, sh_flag
    elif n_missing == 1:
        valid_vals = [v for v in vals if not np.isnan(v)]
        s = sum(valid_vals)
        total = round_half_up(s * 9 / 8)
        prorated = True
    else:
        total = int(sum(vals))
        prorated = False

    # band
    if pd.isna(total):
        band = np.nan
    else:
        if total <= 4:
            band = 'none-minimal'
        elif total <= 9:
            band = 'mild'
        elif total <= 14:
            band = 'moderate'
        elif total <= 19:
            band = 'moderately severe'
        else:
            band = 'severe'

    return total, band, prorated, sh_flag

def score_gad7(row):
    cols = [f'gad7_{i}' for i in range(1, 8)]
    vals = []
    for c in cols:
        v = row[c]
        if pd.isna(v) or v < 0 or v > 3:
            vals.append(np.nan)
        else:
            vals.append(int(v))

    n_missing = pd.isna(vals).sum()
    if n_missing >= 2:
        return np.nan, np.nan, np.nan
    elif n_missing == 1:
        valid_vals = [v for v in vals if not np.isnan(v)]
        s = sum(valid_vals)
        total = round_half_up(s * 7 / 6)
        prorated = True
    else:
        total = int(sum(vals))
        prorated = False

    if pd.isna(total):
        band = np.nan
    else:
        if total <= 4:
            band = 'minimal'
        elif total <= 9:
            band = 'mild'
        elif total <= 14:
            band = 'moderate'
        else:
            band = 'severe'

    return total, band, prorated

def score_rses(row):
    cols = [f'rses_{i}' for i in range(1, 11)]
    rev_items = {3, 5, 8, 9, 10}
    vals = []
    for i, c in enumerate(cols, 1):
        v = row[c]
        if pd.isna(v) or v < 0 or v > 3:
            vals.append(np.nan)
        else:
            iv = int(v)
            if i in rev_items:
                vals.append(3 - iv)
            else:
                vals.append(iv)

    n_missing = pd.isna(vals).sum()
    if n_missing >= 2:
        return np.nan, np.nan
    elif n_missing == 1:
        valid_vals = [v for v in vals if not np.isnan(v)]
        s = sum(valid_vals)
        total = round_half_up(s * 10 / 9)
        prorated = True
    else:
        total = int(sum(vals))
        prorated = False

    return total, prorated

res_list = []
for idx, row in raw.iterrows():
    p_tot, p_band, p_pro, p_sh = score_phq9(row)
    g_tot, g_band, g_pro = score_gad7(row)
    r_tot, r_pro = score_rses(row)
    res_list.append({
        'respondent_id': row['respondent_id'],
        'phq9_total': p_tot,
        'phq9_band': p_band,
        'phq9_prorated': p_pro,
        'phq9_self_harm_flag': p_sh,
        'gad7_total': g_tot,
        'gad7_band': g_band,
        'gad7_prorated': g_pro,
        'rses_total': r_tot,
        'rses_prorated': r_pro
    })

my_output = pd.DataFrame(res_list)

# Compare with pipeline
for col in pipeline.columns:
    if col == 'respondent_id':
        continue
    # compare series
    match = my_output[col].equals(pipeline[col])
    print(f"Column {col}: match = {match}")
    if not match:
        diffs = (my_output[col] != pipeline[col]) & ~(my_output[col].isna() & pipeline[col].isna())
        print(f"  Number of differences: {diffs.sum()}")
        # print some examples
        bad_idx = diffs[diffs].index[:5]
        for i in bad_idx:
            print(f"    Row {i} ({raw.loc[i, 'respondent_id']}): my={my_output.loc[i, col]}, pipe={pipeline.loc[i, col]}")
"}

